From 383b16d5c6e5dddd14a44bd0bd741b4a614da0e1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:23:59 +0100
Subject: [PATCH] activitymanager: show an OSD when switching activity

Switching activity gave no feedback besides the windows disappearing,
which made an accidental switch look like a crash. Now the switch shows
the usual on-screen display with the new activity's icon and name.

BUG: 349004
---
 imports/activitymanager/switcherbackend.cpp | 10 ++++++++++
 1 file changed, 10 insertions(+)

diff --git a/imports/activitymanager/switcherbackend.cpp b/imports/activitymanager/switcherbackend.cpp
index 3744bc1fe2..0e4df0cc0b 100644
--- a/imports/activitymanager/switcherbackend.cpp
+++ b/imports/activitymanager/switcherbackend.cpp
@@ -295,6 +295,16 @@ void SwitcherBackend::onCurrentActivityChanged(const QString &id)
     KActivities::Info activity(id);
     Q_EMIT showSwitchNotification(id, activity.name(), activity.icon());

+    if (!m_previousActivity.isEmpty()) {
+        auto message = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
+                                                      QStringLiteral("/org/kde/osdService"),
+                                                      QStringLiteral("org.kde.osdService"),
+                                                      QStringLiteral("showText"));
+        const QString icon = activity.icon().isEmpty() ? QStringLiteral("activities") : activity.icon();
+        message.setArguments({icon, activity.name()});
+        QDBusConnection::sessionBus().call(message, QDBus::NoBlock);
+    }
+
     KConfig config(QStringLiteral("plasma/activitiesstaterc"), KConfig::SimpleConfig, QStandardPaths::GenericStateLocation);
     KConfigGroup times(&config, QStringLiteral("LastUsed"));

